const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function preview(path){const u=new URL(path,BASE);u.searchParams.set('preview_theme_id',THEME);return u.toString()}
async function go(page,path){let last;for(let i=0;i<5;i++){try{const r=await page.goto(preview(path),{waitUntil:'domcontentloaded',timeout:90000});if(r?.status()===200)return r;last=new Error('HTTP '+(r?.status()||0))}catch(e){last=e}await sleep([4000,7000,11000,16000,22000][i])}throw last||new Error('navigation failed')}
async function settle(page){await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',null,{timeout:45000});await page.waitForFunction(()=>{const m=document.querySelector('#MainContent');if(!m||!m.querySelector('.sq-refine-v3-sidebar'))return false;const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const grids=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];return grids.some(g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]')))},null,{timeout:45000});await sleep(900)}
async function inspect(page){return page.evaluate(()=>{const m=document.querySelector('#MainContent');const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)>0};const allGrids=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const hasProduct=g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]'));const grid=allGrids.find(g=>g.classList.contains('sq-v3-authoritative-grid')&&hasProduct(g))||allGrids.find(hasProduct)||allGrids.find(vis)||null;const cards=grid?[...grid.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')):[];const rects=cards.slice(0,12).map(x=>x.getBoundingClientRect());const row=rects.length?rects.filter(r=>Math.abs(r.y-rects[0].y)<4):[];const side=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis);const legacy=[...m.querySelectorAll('.sq-global-refine-sidebar,.sq-collection-sidebar,.facets-block-wrapper,.facets-container,.facets-wrapper,[class*="filter-sidebar"]')].filter(e=>vis(e)&&!e.classList.contains('sq-refine-v3-sidebar'));const s=side[0],t=s?.querySelector('.sq-refine-v3-sidebar__title'),sr=s?.getBoundingClientRect(),tr=t?.getBoundingClientRect();const groups=s?[...s.querySelectorAll(':scope > details.sq-refine-v3-group')].map(d=>({label:(d.querySelector(':scope > summary')?.textContent||'').trim(),inputs:d.querySelectorAll('input[type=checkbox]').length,targets:[...d.querySelectorAll('input[data-kind=structural][data-target]')].map(i=>i.dataset.target||''),native:[...d.querySelectorAll('input[data-kind=native]')].map(i=>({name:i.dataset.filterName||'',value:i.dataset.filterValue||''}))})):[];return{ready:m?.dataset.sqRefineV3Ready||'',error:m?.dataset.sqRefineV3Error||'',v3:side.length,legacy:legacy.map(e=>typeof e.className==='string'?e.className:e.tagName),sidebarPosition:s?getComputedStyle(s).position:'',sidebarBg:s?getComputedStyle(s).backgroundColor:'',title:(t?.textContent||'').trim(),titleBg:t?getComputedStyle(t).backgroundColor:'',titleRightGap:sr&&tr?Math.max(0,sr.right-tr.right):999,gridClass:grid?.className||'',gridWidth:grid?Math.round(grid.getBoundingClientRect().width):0,cards:cards.length,firstRowCount:row.length,cardWidth:row.length?Math.round(row.map(r=>r.width).sort((a,b)=>a-b)[Math.floor(row.length/2)]):0,groups,pageSizes:[...m.querySelectorAll('.sq-refine-v3-page-size input')].map(i=>i.value)}})}
function validate(name,path,d){const e=[];if(d.ready!=='true')e.push('not ready');if(d.error)e.push('runtime '+d.error);if(d.v3!==1)e.push('visible V3 sidebars '+d.v3);if(d.legacy.length)e.push('visible legacy sidebars '+d.legacy.join(','));if(d.sidebarPosition!=='sticky')e.push('sidebar '+d.sidebarPosition);if(d.sidebarBg!=='rgb(8, 40, 63)'||d.titleBg!=='rgb(8, 40, 63)'||d.title.toUpperCase()!=='REFINE PRODUCTS'||d.titleRightGap>1.5)e.push('refine header edge/color');if(d.cards<1)e.push('no visible products');if(d.firstRowCount!==3)e.push('desktop row '+d.firstRowCount);if(d.cardWidth<250)e.push('card width '+d.cardWidth);if(d.pageSizes.join(',')!=='50,100,250')e.push('page sizes '+d.pageSizes.join(','));const labels=d.groups.map(g=>g.label);if(!labels.includes('Shop by Type'))e.push('missing Shop by Type');if(!labels.includes('Shop by Manufacturers'))e.push('missing Shop by Manufacturers');for(const g of d.groups){if(g.inputs<1)e.push('empty '+g.label);for(const x of g.targets){if(!x.startsWith('/collections/'))e.push('bad structural target '+g.label);else if(!new URL(x,BASE).searchParams.get('sq_root'))e.push('missing sq_root '+g.label)}}if(path==='/collections/literature'){for(const req of ['Shop by Publisher','Shop by War / Era / Conflict','Shop by Branch','Shop by Topic'])if(!labels.some(x=>x===req||x.startsWith(req)))e.push('missing '+req);const author=d.groups.find(g=>g.label==='Shop by Author');if(author&&author.targets.some(x=>!x.startsWith('/collections/')))e.push('unsafe Shop by Author');}if(path==='/collections/firearm-accessories'&&!labels.includes('Shop by Make / Model'))e.push('missing Shop by Make / Model');return e}

const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:1440,height:1000}});const page=await ctx.newPage();const results=[];let errors=[];page.on('pageerror',e=>{if(/sq-refine|sq-v3/i.test(e.stack||e.message||''))errors.push('pageerror '+e.message)});
for(let i=0;i<routes.length;i++){const[name,path,type]=routes[i];if(type==='legacy'){try{const r=await go(page,path);await sleep(800);const x=await page.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')}));const e=[];if(r?.status()!==200)e.push('HTTP');if(x.v3||x.side)e.push('legacy route contaminated by V3');results.push({index:i+1,name,path,type,pass:!e.length,errors:e,data:x});console.log((e.length?'FAIL ':'PASS ')+(i+1)+'/41 '+name+(e.length?' :: '+e.join(' | '):''))}catch(err){results.push({index:i+1,name,path,type,pass:false,errors:[String(err)]});console.log('FAIL '+(i+1)+'/41 '+name+' :: '+err)}continue}try{await go(page,path);await settle(page);const d=await inspect(page);const e=validate(name,path,d);results.push({index:i+1,name,path,type,pass:!e.length,errors:e,data:d});console.log((e.length?'FAIL ':'PASS ')+(i+1)+'/41 '+name+(e.length?' :: '+e.join(' | '):''))}catch(err){results.push({index:i+1,name,path,type,pass:false,errors:[String(err)]});console.log('FAIL '+(i+1)+'/41 '+name+' :: '+err)}await sleep(900)}

// State Guard freeze.
let stateGuard={pass:false};try{const r=await go(page,'/collections/state-guard-series');await sleep(1200);const x=await page.evaluate(()=>({v3:!!document.querySelector('[data-sq-refine-v3]'),side:!!document.querySelector('.sq-refine-v3-sidebar')}));stateGuard={pass:r?.status()===200&&!x.v3&&!x.side,data:x}}catch(e){stateGuard={pass:false,error:String(e)}}

// Mobile visible authoritative grids must be two columns and one static sidebar.
let mobile={pass:true,routes:[]};const mc=await browser.newContext({viewport:{width:390,height:844}});const mp=await mc.newPage();for(const path of ['/collections/accessories-gifts-collectibles','/collections/apparel','/collections/literature','/collections/products-built-for-the-line-u-s-navy']){try{await go(mp,path);await settle(mp);const d=await mp.evaluate(()=>{const vis=e=>{if(!e)return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>1&&r.height>1&&s.display!=='none'&&s.visibility!=='hidden'};const m=document.querySelector('#MainContent');const sides=[...m.querySelectorAll('.sq-refine-v3-sidebar')].filter(vis);const grids=[...m.querySelectorAll('.sq-refine-v3-results .product-grid')];const has=g=>vis(g)&&[...g.querySelectorAll(':scope > .product-grid__item')].some(x=>vis(x)&&x.querySelector('a[href*="/products/"]'));const g=grids.find(x=>x.classList.contains('sq-v3-authoritative-grid')&&has(x))||grids.find(has);const cards=g?[...g.querySelectorAll(':scope > .product-grid__item')].filter(x=>vis(x)&&x.querySelector('a[href*="/products/"]')).slice(0,8):[];const rs=cards.map(x=>x.getBoundingClientRect()),row=rs.length?rs.filter(x=>Math.abs(x.y-rs[0].y)<4).length:0;return{sidebars:sides.length,position:sides[0]?getComputedStyle(sides[0]).position:'',row,cards:cards.length}});const pass=d.sidebars===1&&d.position!=='sticky'&&d.row===2&&d.cards>=2;mobile.routes.push({path,pass,data:d});if(!pass)mobile.pass=false}catch(e){mobile.routes.push({path,pass:false,error:String(e)});mobile.pass=false}}await mc.close();

const passed=results.filter(r=>r.pass).length;const report={theme:THEME,requested:41,passed,failed:41-passed,stateGuard,mobile,pageErrors:errors,results,overallPass:passed===41&&stateGuard.pass&&mobile.pass&&!errors.length};fs.writeFileSync(OUT+'/report.json',JSON.stringify(report,null,2));fs.writeFileSync(OUT+'/summary.txt',`requested 41\npassed ${passed}\nfailed ${41-passed}\nstateGuard ${stateGuard.pass}\nmobile ${mobile.pass}\npageErrors ${errors.length}\noverall ${report.overallPass}\n`);console.log('SUMMARY '+JSON.stringify({requested:41,passed,failed:41-passed,stateGuard:stateGuard.pass,mobile:mobile.pass,pageErrors:errors.length,overallPass:report.overallPass}));await ctx.close();await browser.close();if(!report.overallPass)process.exit(1);
